import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False,
        )
    )

    nonempty = [
        (index, row)
        for index, row in enumerate(records)
        if row and any(cell.strip() for cell in row)
    ]
    if not nonempty:
        return {"columns": [], "rows": []}

    expected_width = 12

    def header_score(item: tuple[int, list[str]]) -> tuple[float, ...]:
        index, row = item
        values = [cell.strip() for cell in row]
        nonempty_count = sum(bool(value) for value in values)
        unique_count = len(set(value.casefold() for value in values if value))
        textual_count = sum(bool(re.search(r"[A-Za-z]", value)) for value in values)
        numeric_count = sum(
            bool(re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", value))
            for value in values
        )
        return (
            float(len(row) == expected_width),
            nonempty_count / max(len(row), 1),
            unique_count / max(nonempty_count, 1),
            textual_count / max(len(row), 1),
            -numeric_count / max(len(row), 1),
            -float(index),
        )

    header_index, header = max(nonempty, key=header_score)
    width = len(header)

    if width < 1:
        return {"columns": [], "rows": []}

    columns = [cell.strip() for cell in header]
    rows = []

    for row in records[header_index + 1 :]:
        if not row or not any(cell.strip() for cell in row):
            continue
        if len(row) < width:
            normalized = row + [""] * (width - len(row))
        elif len(row) > width:
            normalized = row[: width - 1] + [",".join(row[width - 1 :])]
        else:
            normalized = row[:]
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
